-- Generated puzzle themes (AI-made collections) served to the app by the API.
--
-- A THEME is the unit, like "Magic Garden": it has a title, a description, a type and a fixed number
-- of puzzles. Its title is the collection_type used by collection_puzzles / user_collections, so a
-- finished puzzle is collected by the existing flow and My Collections shows one section per theme.
-- A theme is only served once it has all `puzzle_count` puzzles, and the count never changes after
-- publishing (players' "3/6" progress would change).
--
-- generated_puzzles keeps the artwork compactly so a new theme is an INSERT, not an app release:
--   palette: [{color, nutrient}] (nutrient 1 carbs, 2 protein, 3 fats) in the order a nutrient's colours fill
--   grid:    24 rows of 24 palette indexes (-1 = empty background cell)
-- Pixel shares follow the product's daily-goal split (60% carbs / 24% protein / 16% fats of goal grams) and
-- each theme is checked by backend/scripts/puzzle-generator/validate.mjs before it is exported.
-- Only the API (service role) reads these tables; browsers do not.
create table public.puzzle_themes (
  id text primary key,
  title text not null unique check (title not in ('Magic Garden', 'Salmon Nigiri Boy')),
  description text not null,
  type text not null default 'collection' check (type in ('collection')),
  puzzle_count integer not null check (puzzle_count between 2 and 12),
  bg_color text not null,
  published boolean not null default false,
  created_at timestamptz not null default now()
);

create table public.generated_puzzles (
  id text primary key,
  theme_id text not null references public.puzzle_themes (id) on delete cascade,
  slot integer not null check (slot >= 1),
  name text not null unique,
  description text not null,
  descriptions jsonb not null check (jsonb_typeof(descriptions) = 'array' and jsonb_array_length(descriptions) = 5),
  bg_color text not null,
  palette jsonb not null,
  grid jsonb not null check (jsonb_typeof(grid) = 'array' and jsonb_array_length(grid) = 24),
  created_at timestamptz not null default now(),
  unique (theme_id, slot)
);

create index generated_puzzles_theme_idx on public.generated_puzzles (theme_id);

alter table public.puzzle_themes enable row level security;
alter table public.generated_puzzles enable row level security;
revoke all on public.puzzle_themes, public.generated_puzzles from anon, authenticated;

insert into public.puzzle_themes (id, title, description, type, puzzle_count, bg_color, published) values ('breakfast_club', 'Breakfast Club', 'Start your day right by completing daily nutrition challenges and collecting 6 delicious breakfast-themed puzzles. Each puzzle brings you closer to building a wholesome morning meal. Rise and shine with every nutritious bite!', 'collection', 6, '#D8E8E7', true);
